// Generate trend-based search queries from multiple signals
const now = new Date();
const year = now.getFullYear();
const month = now.getMonth() + 1;
const isRamadan = month >= 3 && month <= 4; // approximate Ramadan window

const queries = [
  // Trending by year/recency
  { query: `أفضل الأفلام التركية المدبلجة ${year}`,        origin: 'turkish',  type: 'film'   },
  { query: `أفضل مسلسلات كورية مدبلجة بالعربية ${year}`,   origin: 'korean',   type: 'series' },
  { query: `أفضل الأفلام الهندية المدبلجة ${year}`,        origin: 'indian',   type: 'film'   },
  { query: `مسلسل صيني رومانسي مدبلج عربي ${year}`,        origin: 'chinese',  type: 'series' },
  { query: `أفلام صينية مدبلجة بالعربية كاملة ${year}`,   origin: 'chinese',  type: 'film'   },
  { query: `أفلام أمريكية أكشن مدبلجة كاملة ${year}`,      origin: 'american', type: 'film'   },
  // Moroccan trending
  { query: 'أفضل الأفلام المغربية 2024',                   origin: 'moroccan', type: 'film'   },
  { query: 'مسلسلات مغربية بالدارجة جديدة',                origin: 'moroccan', type: 'series' },
];

// Add Ramadan specials if applicable
if (isRamadan) {
  queries.push(
    { query: `مسلسلات رمضان ${year} المغربية`,     origin: 'moroccan', type: 'series' },
    { query: `مسلسلات رمضان ${year} تركية مدبلجة`, origin: 'turkish',  type: 'series' }
  );
}

console.log(`[Trends] Generated ${queries.length} trend queries`);
return queries.map(q => ({ json: q }));

const results = $input.first().json.results || [];
const query = $('Generate Trend Queries').item.json;

// For trend content, we use a slightly lower bar — min 30min for films
const minDuration = query.type === 'film' ? 1800 : 600;

const filtered = results
  .filter(r => r.embeddable !== false)
  .filter(r => !r.duration_sec || r.duration_sec >= minDuration)
  .map(r => ({
    ...r,
    origin:   (r.origin && r.origin !== 'other') ? r.origin : query.origin,
    language: r.language,
    query:    query.query,
    trend_source: 'trend_hunter'
  }));

console.log(`[Trends] ${query.query} → ${filtered.length} trend items`);
return filtered.length ? [{ json: { items: filtered, type: query.type } }] : [];

const items = $input.all();
let imported=0, skipped=0;
for (const item of items) {
  imported += item.json.imported || 0;
  skipped  += item.json.skipped  || 0;
}
console.log(`[Trends] DONE: ${imported} new trends imported, ${skipped} already existed`);
return [{ json: { imported, skipped, run_at: new Date().toISOString() } }];
